const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const dcGeometry = ee.Geometry.Polygon([
    [-77.1198, 38.7916],
    [-77.0328, 38.7916],
    [-77.0328, 38.9956],
    [-77.1198, 38.9956],
    [-77.1198, 38.7916]
  ]);

  const startDate = '2018-01-01';
  const endDate = '2018-12-31';

  // 2. Data Acquisition - CHIRPS Daily Precipitation
  const chirpsCollection = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
    .filterDate(startDate, endDate)
    .filterBounds(dcGeometry);

  const collectionSize = chirpsCollection.size().getInfo();
  console.log(`2018 CHIRPS Images: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("No precipitation data found for 2018.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Calculate annual precipitation sum
  const annualPrecip = chirpsCollection.sum();

  // 4. Check for valid pixels
  const pixelCount = annualPrecip.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: dcGeometry,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  console.log(`Valid pixels in region: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log("No valid precipitation pixels in region.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 5. Calculate mean annual precipitation (mm)
  const meanAnnualPrecip = annualPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: dcGeometry,
    scale: 5000,
    maxPixels: 1e9
  }).get('precipitation').getInfo();

  // Convert mm to inches
  const annualRainfallInches = meanAnnualPrecip / 25.4;

  console.log(`Annual rainfall: ${annualRainfallInches.toFixed(2)} inches`);

  // 6. Validation & Final Answer
  if (meanAnnualPrecip === null || isNaN(meanAnnualPrecip) || annualRainfallInches < 0 || annualRainfallInches > 200) {
    console.log("Invalid precipitation calculation result.");
    console.log("<answer>C3</answer>");
  } else if (annualRainfallInches >= 50) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
